import json
import pandas as pd
import numpy as np

FIELDS = ["name", "email", "created_date", "status"]
SOURCE_KEYS = ["source_a", "source_b", "source_c"]

def norm_status(v):
    if v is None:
        return None
    if isinstance(v, (bool, np.bool_)):
        return "active" if v else "inactive"
    s = str(v).strip()
    if s == "" or s.lower() in ("na", "nan", "none"):
        return None
    sl = s.lower()
    if sl in ("true", "1"):
        return "active"
    if sl in ("false", "0"):
        return "inactive"
    return s

def norm_date(v):
    if v is None:
        return None
    if isinstance(v, pd.Timestamp):
        return v.strftime("%Y-%m-%d")
    s = str(v).strip()
    if s == "" or s.lower() in ("na", "nan", "none"):
        return None
    try:
        return pd.to_datetime(s).strftime("%Y-%m-%d")
    except Exception:
        return s[:10]

def norm_str(v):
    if v is None:
        return None
    if isinstance(v, float) and np.isnan(v):
        return None
    s = str(v).strip()
    return s if s and s.lower() not in ("na", "nan", "none") else None

def to_int(v):
    return int(float(v))

def build_source(records, mapping):
    out = {}
    for rec in records:
        rec = dict(rec)
        uid = to_int(rec[mapping["user_id"]])
        row = {}
        for std, src in mapping.items():
            if src == "user_id":
                continue
            raw = rec.get(src)
            if std == "created_date":
                row[std] = norm_date(raw)
            elif std == "status":
                row[std] = norm_status(raw)
            else:
                row[std] = norm_str(raw)
        out[uid] = row
    return out

with open("/data/source_a/users.json") as f:
    src_a_records = json.load(f)
src_a = build_source(src_a_records, {
    "user_id": "id", "name": "full_name", "email": "email",
    "created_date": "registration_date", "status": "status"})

src_b = build_source(pd.read_csv("/data/source_b/users.csv", dtype=str).to_dict("records"), {
    "user_id": "user_id", "name": "name", "email": "email_address",
    "created_date": "created_at", "status": "is_active"})

src_c = build_source(pd.read_parquet("/data/source_c/users.parquet").to_dict("records"), {
    "user_id": "userId", "name": "userName", "email": "email",
    "created_date": "joined", "status": "active"})

sources = {"source_a": src_a, "source_b": src_b, "source_c": src_c}

all_ids = sorted(set(src_a) | set(src_b) | set(src_c))
merged = {}
conflicts = []

for uid in all_ids:
    merged[uid] = {"user_id": uid}
    for field in FIELDS:
        values = {}
        for key in SOURCE_KEYS:
            values[key] = sources[key].get(uid, {}).get(field)
        selected = None
        for key in SOURCE_KEYS:
            if values[key] is not None:
                selected = values[key]
                break
        merged[uid][field] = selected
        distinct = set(v for v in values.values() if v is not None)
        if len(distinct) > 1:
            conflicts.append({
                "user_id": uid,
                "field": field,
                "values": values,
                "selected": selected,
            })

df = pd.DataFrame([merged[uid] for uid in all_ids],
                  columns=["user_id", "name", "email", "created_date", "status"])
df["user_id"] = df["user_id"].astype("int64")
for col in ["name", "email", "created_date", "status"]:
    df[col] = df[col].astype("object")
df.to_parquet("/app/merged_users.parquet", index=False)

report = {"total_conflicts": len(conflicts), "conflicts": conflicts}
with open("/app/conflicts.json", "w") as f:
    json.dump(report, f, indent=2)

print("merged rows:", len(df))
print(df.to_string())
print("conflicts:", len(conflicts))
PYEOF
